#!/bin/bash
# AI generated by GitHub Copilot (DeepSeek V4 Pro), v1.0
#
# Shell script to execute Docker container with volume mapping
# Maps current directory to /workspace in container
#
# Usage (from collectdata/):
#   ./build_container/run_container.sh                     # reconfigure + build
#   ./build_container/run_container.sh make check          # run the tests
#   ./build_container/run_container.sh ./reconfigure.sh --without-fox
#   ./build_container/run_container.sh bash                # interactive shell
#
# The submodules (cpputils) have to be checked out on the host first:
#   git submodule update --init --recursive

set -e

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CURRENT_DIR="$(pwd)"
IMAGE_NAME="pi-sensor-build-container"
CONTAINER_NAME="pi-sensor-build"

if [ "$#" -eq 0 ] ; then
	set -- ./reconfigure.sh "&&" make "-j$(nproc)"
fi

echo "Building Docker image..."
docker build -t "$IMAGE_NAME" "$SCRIPT_DIR"

echo "Running container with volume mapping..."
echo "  Image: $IMAGE_NAME"
echo "  Container: $CONTAINER_NAME"
echo "  Local directory: $CURRENT_DIR"
echo "  Container mount: /workspace"

docker run --rm -t \
  --user $(id -u):$(id -g) \
  --name "$CONTAINER_NAME" \
  -v "$CURRENT_DIR:/workspace" \
  -w /workspace \
  "$IMAGE_NAME" \
  /bin/bash -c "$*"

echo "Container execution completed."
